const riverTile = `-- name: RiverTile :one
WITH bounds AS (
    SELECT ST_TileEnvelope($1::int, $2::int, $3::int) AS tile,
           ST_TileEnvelope($1::int, $2::int, $3::int, margin => 64.0 / 4096) AS area
),
reaches AS (
    SELECT p.reach_fid AS fid, p.reach_fid AS reach, p.river_id AS river, p.river_name AS name, p.named,
           p.width_class AS width,
           ST_AsMVTGeom(p.geom_3857, bounds.tile, 4096, 64, true) AS geom
    FROM river_reach_parts p, bounds
    WHERE p.geom_3857 && bounds.area AND p.min_zoom <= $1::int
),
streams AS (
    SELECT s.hyriv_id AS fid, coalesce(s.river_id, '') AS river,
           (CASE WHEN s.upland_km2 >= 100 THEN 2 ELSE 1 END)::int AS width,
           ST_AsMVTGeom(s.geom_3857, bounds.tile, 4096, 64, true) AS geom
    FROM river_segments s, bounds
    WHERE s.geom_3857 && bounds.area AND s.reach_fid IS NULL AND s.upland_km2 >= $4::float8
),
labels AS (
    SELECT rv.id AS river, rv.name, (rv.parent_id IS NULL)::boolean AS main, rv.upland_km2::int AS upland,
           ST_AsMVTGeom(rv.label_geom, bounds.tile, 4096, 64, true) AS geom
    FROM rivers rv, bounds
    WHERE rv.named AND rv.label_geom && bounds.area
)
SELECT (coalesce((SELECT ST_AsMVT(f, 'reaches', 4096, 'geom', 'fid') FROM (SELECT fid, reach, river, name, named, width, geom FROM reaches WHERE geom IS NOT NULL) f), ''::bytea)
     || coalesce((SELECT ST_AsMVT(f, 'streams', 4096, 'geom', 'fid') FROM (SELECT fid, river, width, geom FROM streams WHERE geom IS NOT NULL) f), ''::bytea)
     || coalesce((SELECT ST_AsMVT(f, 'labels', 4096, 'geom') FROM (SELECT river, name, main, upland, geom FROM labels WHERE geom IS NOT NULL) f), ''::bytea)
       )::bytea AS tile
`

type RiverTileParams struct {
	Z         int32   `json:"z"`
	X         int32   `json:"x"`
	Y         int32   `json:"y"`
	MinUpland float64 `json:"min_upland"`
}

// One Mapbox Vector Tile with the drawn reaches, the other streams by zoom and
// the lines names are placed along.
func (q *Queries) RiverTile(ctx context.Context, arg RiverTileParams) ([]byte, error) {
	row := q.db.QueryRow(ctx, riverTile,
		arg.Z,
		arg.X,
		arg.Y,
		arg.MinUpland,
	)
	var tile []byte
	err := row.Scan(&tile)
	return tile, err
}

const riversNear = `-- name: RiversNear :many
SELECT DISTINCT ON (q.river_id) q.river_id, q.fid,
       ST_Distance(q.geom::geography, ST_SetSRID(ST_MakePoint($1::float8, $2::float8), 4326)::geography)::float8 AS distance_m
FROM river_reaches q
WHERE ST_DWithin(q.geom, ST_SetSRID(ST_MakePoint($1::float8, $2::float8), 4326), $3::float8)
ORDER BY q.river_id, distance_m
`

